package main

import (
	"fmt"
	"strings"
	"net/http"
	"io"
)

func main() {

	url := "https://www.nutanix.dev/foundation/abort_session"

	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		fmt.Println("Error creating request:", err)
		return
	}


	res, err := http.DefaultClient.Do(req)
	if err != nil {
		fmt.Println("Error creating request:", err)
		return
	}

	defer res.Body.Close()
	body, err := io.ReadAll(res.Body)
	if err != nil {
		fmt.Println("Error creating request:", err)
		return
	}

	fmt.Println(res)
	fmt.Println(string(body))

}

AsyncHttpClient client = new DefaultAsyncHttpClient();
client.prepare("GET", "https://www.nutanix.dev/foundation/abort_session")
  .execute()
  .toCompletableFuture()
  .thenAccept(System.out::println)
  .join();

client.close();

const url = 'https://www.nutanix.dev/foundation/abort_session';
const options = {
  method: 'GET',
  headers: {} 
};

try {
  const response = await fetch(url, options);
  const data = await response.json();
  console.log(data);
} catch (error) {
  console.error(error);
}

